/**
 * ShamirDB Node.js client SDK — typed-error surface.
 *
 * This is the package entry point (`package.json` → `main`). The raw native
 * binding is in `native/index.js` (auto-generated by napi-rs); this wrapper adds
 * ShamirDbError and object-level execute/repl/createScramUser.
 */

/**
 * Server error codes that are transient — the same request may succeed on a
 * retry.
 */
export declare const RETRYABLE_ERROR_CODES: ReadonlySet<string>;

/** `true` if `code` is a transient failure worth retrying. */
export declare function isRetryableCode(code: string): boolean;

/**
 * A typed DB-layer error carrying the server's `code` and a `retryable`
 * classification. Thrown for every `DbResponse::Error` the server returns
 * from `execute`, `repl`, or `createScramUser`.
 *
 * Mirrors the TS SDK's `ShamirDbError` (`shamir-client-ts/src/core/support/errors.ts`).
 */
export declare class ShamirDbError extends Error {
  /** Server error code (e.g. "timeout", "validation", "tx_conflict"). */
  readonly code: string;
  /** Human-readable detail returned by the server (without the code prefix). */
  readonly detail: string;
  /** Whether retrying the same request may succeed. */
  readonly retryable: boolean;
}

/** Connection parameters. */
export interface ConnectOptions {
  host: string;
  port: number;
  serverName: string;
  username: string;
  /** The owned native password buffer is zeroized on drop, not JS copies. */
  password: string;
  acceptNewHost?: boolean;
  trustedPin?: Buffer;
  /** Deadline (ms) for the TCP connect attempt. */
  connectTimeoutMs?: number;
  /**
   * Deadline (ms) for the WHOLE connect: DNS resolution, TCP, TLS and
   * SCRAM. Omitted = unbounded (prior behaviour).
   */
  handshakeTimeoutMs?: number;
  /** Deadline (ms) for each request/response call, from the moment the call starts. */
  requestTimeoutMs?: number;
}

/**
 * Plain-TCP connection parameters. Only loopback hosts are accepted.
 */
export interface ConnectPlainOptions {
  host: string;
  port: number;
  username: string;
  /** A JavaScript string cannot be wiped by the library; only the native copy is zeroized. */
  password: string;
  acceptNewHost?: boolean;
  trustedPin?: Buffer;
  connectTimeoutMs?: number;
  handshakeTimeoutMs?: number;
  requestTimeoutMs?: number;
}

/** Local-socket connection parameters. */
export interface ConnectLocalOptions {
  /** Unix socket path, or a Windows named pipe such as `\\.\pipe\name`. */
  addr: string;
  username: string;
  /** A JavaScript string cannot be wiped by the library; only the native copy is zeroized. */
  password: string;
  acceptNewHost?: boolean;
  trustedPin?: Buffer;
  connectTimeoutMs?: number;
  requestTimeoutMs?: number;
}

/** Session-resume parameters (`resume` / `resumeWs`). */
export interface ResumeOptions {
  host: string;
  port: number;
  serverName: string;
  /**
   * Resumption ticket. A JavaScript Buffer cannot be wiped by the library;
   * only the native copy is zeroized.
   */
  ticket: Buffer;
  /** Required server public-key pin (32 bytes). */
  trustedPin: Buffer;
  handshakeTimeoutMs?: number;
  requestTimeoutMs?: number;
}

/** Token endpoint location and TLS settings. */
export interface TokenEndpointOptions {
  host: string;
  port: number;
  serverName?: string;
  /** Extra CA certificate (PEM) to trust. */
  caPem?: string;
  /** Allow plain HTTP/WS; loopback hosts only. */
  plainLoopback?: boolean;
}

/** Parameters for `ShamirTokenHttpClient.connect`. */
export interface TokenHttpOptions extends TokenEndpointOptions {
  /** A JavaScript string cannot be wiped by the library; only the native copy is zeroized. */
  token: string;
  connectTimeoutMs?: number;
  requestTimeoutMs?: number;
}

/** Parameters for `ShamirClient.connectTokenWs`. */
export interface TokenWsOptions extends TokenEndpointOptions {
  /** A JavaScript string cannot be wiped by the library; only the native copy is zeroized. */
  token: string;
  connectTimeoutMs?: number;
  handshakeTimeoutMs?: number;
  requestTimeoutMs?: number;
}

/** Parameters for `login`. */
export interface LoginOptions extends TokenEndpointOptions {
  username: string;
  /** A JavaScript string cannot be wiped by the library; only the native copy is zeroized. */
  password: string;
  label?: string;
  mode?: 'read_only' | 'read_write';
  channels?: 'rest' | 'ws' | 'both';
  databases?: string[];
  /** 16-byte listener id. */
  listenerId?: Buffer;
  connectTimeoutMs?: number;
  requestTimeoutMs?: number;
}

/** Result of `login`. */
export interface LoginResult {
  /** The secret token; a JavaScript string cannot be wiped by the library. */
  token: string;
  /** 16-byte token id. */
  id: Buffer;
  owner: string;
  label: string;
  mode: 'read_only' | 'read_write';
  channels: 'rest' | 'ws' | 'both';
  /** `null` = all databases. */
  databases: string[] | null;
  createdAtNs: bigint;
  expiresAtNs: bigint;
}

/** Parameters for `ShamirClient.createApiToken`. */
export interface CreateApiTokenOptions {
  label: string;
  ttlSecs?: number;
  mode?: 'read_only' | 'read_write';
  channels?: 'rest' | 'ws' | 'both';
  databases?: string[];
  /** Create the token for another user (superuser only). */
  forUser?: string;
}

/** A newly created API token. */
export interface CreatedApiToken {
  /** Base64url token id (as accepted by revoke calls). */
  id: string;
  /** The secret token; a JavaScript string cannot be wiped by the library. */
  token: string;
  label: string;
  owner: string;
  mode: 'read_only' | 'read_write';
  channels: 'rest' | 'ws' | 'both';
  /** `null` = all databases. */
  databases: string[] | null;
  createdAtNs: bigint;
  expiresAtNs: bigint;
}

/**
 * A connected, authenticated client. This is a subset of the Rust SDK;
 * subscriptions and cursors are not exposed.
 * `execute` accepts a plain JS object and
 * returns a plain JS object (msgpack encode/decode is handled internally).
 *
 * A token session (`connectTokenWs`) refuses admin methods (`createScramUser`,
 * `repl`, `setReplicator`, `createApiToken`) with ShamirDbError code
 * `token_request_denied`, and `serverPubKeyPin()` is 32 zero bytes there.
 */
export declare class ShamirClient {
  static connect(opts: ConnectOptions): Promise<ShamirClient>;
  static connectWs(opts: ConnectOptions): Promise<ShamirClient>;
  /** Loopback hosts only. */
  static connectPlain(opts: ConnectPlainOptions): Promise<ShamirClient>;
  static connectLocal(opts: ConnectLocalOptions): Promise<ShamirClient>;
  static resume(opts: ResumeOptions): Promise<ShamirClient>;
  static resumeWs(opts: ResumeOptions): Promise<ShamirClient>;
  static connectTokenWs(opts: TokenWsOptions): Promise<ShamirClient>;
  authKind(): 'scram' | 'token';
  /** Throws ShamirDbError (`token_request_denied` on token sessions). */
  createApiToken(opts: CreateApiTokenOptions): Promise<CreatedApiToken>;
  serverPubKeyPin(): Buffer;
  /** Empty after close; previously returned buffers remain caller-owned. */
  sessionId(): Buffer;
  expiresAtNs(): bigint;
  /** Input for `resume`; null after close. Previously returned buffers are not erased. */
  resumptionTicket(): Buffer | null;
  resumptionExpiresAtNs(): bigint | null;
  ping(): Promise<void>;
  /**
   * Low-level object FFI: pass a TS Batch builder's `build()` result.
   * `Batch.execute(nodeClient, db)` is unsupported (no executeWithTouch);
   * DTO reexports and a full adapter are deferred.
   * Decoded 64-bit integers are number when safe, otherwise bigint. Supply
   * bigint for unsafe integers; bigint inputs must fit int64 or uint64.
   */
  execute(db: string, batch: object): Promise<object>;
  repl(req: Buffer): Promise<Buffer>;
  createScramUser(name: string, password: string, roles: string[]): Promise<Buffer>;
  /**
   * Grant or revoke the `replicator` role on an existing SCRAM user via the
   * dedicated SetReplicator wire op. Throws ShamirDbError on domain-level DB
   * errors (e.g. "permission_denied", "hmac_required", "not_found").
   */
  setReplicator(user: string, on: boolean): Promise<void>;
  close(): Promise<void>;
}

/** HTTP client authenticated with an API token. */
export declare class ShamirTokenHttpClient {
  static connect(opts: TokenHttpOptions): Promise<ShamirTokenHttpClient>;
  ping(): Promise<void>;
  /** Same object-level contract as `ShamirClient.execute`. */
  execute(db: string, batch: object): Promise<object>;
  close(): Promise<void>;
}

/** Exchange username/password for an API token. Throws ShamirDbError on server errors. */
export declare function login(opts: LoginOptions): Promise<LoginResult>;
